/// The shader sources compiled into the library, used when no resource bundle is found.
enum EmbeddedShaders {
    static let sources: [String: String] = [
"Attention.metal": #"""
// Copyright 2026 Peter Marelas
// SPDX-License-Identifier: Apache-2.0
// Bidirectional flash-style attention over packed variable-length sequences.
//
// Element ownership of a simdgroup_float8x8 on Apple GPUs (measured on M3 Max): lane l holds
// row ((l >> 1) & 3) | ((l >> 4) << 2), columns (l & 1) * 2 + ((l >> 3) & 1) * 4 and the next
// one, so the four lanes that share a row differ in lane bits 0 and 3 and a row reduction is
// simd_shuffle_xor by 1 and by 8.

constant int ATT_KEYS = 32;
constant int ATT_DC = 64;
constant int ATT_LD = ATT_DC + 4;
constant int ATT_TILE_FLOATS = ATT_KEYS * ATT_LD;

// Stages rows [row0, row0 + 32) x columns [col0, col0 + 64) of a [rows][stride] matrix.
inline void stage_tile(threadgroup float* tile, device const float* src, uint stride, uint tid, uint threads) {
    for (uint u = tid; u < ATT_KEYS * ATT_DC / 4; u += threads) {
        const uint r = u / (ATT_DC / 4), c4 = u % (ATT_DC / 4);
        const float4 v = *(device const float4*)(src + r * stride + c4 * 4);
        threadgroup float* dst = tile + r * ATT_LD + c4 * 4;
        dst[0] = v.x; dst[1] = v.y; dst[2] = v.z; dst[3] = v.w;
    }
}

template <int ATT_DS>
kernel void attention_kernel(device const float* Q [[buffer(0)]],
                             device const float* K [[buffer(1)]],
                             device const float* V [[buffer(2)]],
                             device float* O [[buffer(3)]],
                             device const AttentionWork* work [[buffer(4)]],
                             constant AttentionParams& p [[buffer(5)]],
                             threadgroup float* tile [[threadgroup(0)]],
                             uint3 tgid [[threadgroup_position_in_grid]],
                             uint tid [[thread_index_in_threadgroup]],
                             uint sgid [[simdgroup_index_in_threadgroup]],
                             uint lane [[thread_index_in_simdgroup]]) {
    const AttentionWork w = work[tgid.x];
    const uint h = tgid.y;
    const uint slice = tgid.z;
    const uint kh = h / (p.heads / p.kvHeads);
    const uint hd = p.headDim;
    const uint d0 = slice * ATT_DS;
    const uint len = w.seqLen;
    const uint simdgroups = p.queriesPerGroup / 8;
    const uint threads = simdgroups * 32;
    const uint qRow0 = w.q0 + sgid * 8;
    const uint hw = p.halfWindow;

    device const float* qBase = Q + (w.seqStart + qRow0) * p.qStride + h * hd;
    device const float* kBase = K + w.seqStart * p.kvStride + kh * hd;
    device const float* vBase = V + w.seqStart * p.kvStride + kh * hd + d0;

    // Every loop over o[] is fully unrolled so each index is a compile-time constant and the
    // accumulators stay in registers; a single runtime index puts the whole array in memory and
    // made the kernel about twice as slow.
    simdgroup_float8x8 o[ATT_DS / 8];
    #pragma clang loop unroll(full)
    for (int c = 0; c < ATT_DS / 8; c++) o[c] = simdgroup_float8x8(0.0f);

    const uint r = ((lane >> 1) & 3) | ((lane >> 4) << 2);
    const uint c0 = (lane & 1) * 2 + ((lane >> 3) & 1) * 4;
    const int qi = int(qRow0 + r);
    float m = -INFINITY;
    float l = 0.0f;

    // Key range for the whole query block, clipped to the window; every simdgroup walks it
    // because the K and V tiles are shared.
    uint kStart = 0, kEnd = len;
    if (hw > 0) {
        const int lo = int(w.q0) - int(hw);
        const int hi = int(w.q0) + int(p.queriesPerGroup) - 1 + int(hw) + 1;
        kStart = uint(max(lo, 0));
        kEnd = min(uint(max(hi, 0)), len);
    }
    kStart = kStart / ATT_KEYS * ATT_KEYS;

    for (uint kb = kStart; kb < kEnd; kb += ATT_KEYS) {
        simdgroup_float8x8 s[4];
        for (int j = 0; j < 4; j++) s[j] = simdgroup_float8x8(0.0f);
        for (uint dc = 0; dc < hd; dc += ATT_DC) {
            threadgroup_barrier(mem_flags::mem_threadgroup);
            stage_tile(tile, kBase + kb * p.kvStride + dc, p.kvStride, tid, threads);
            threadgroup_barrier(mem_flags::mem_threadgroup);
            for (int dd = 0; dd < ATT_DC; dd += 8) {
                simdgroup_float8x8 a;
                simdgroup_load(a, qBase + dc + dd, p.qStride);
                for (int j = 0; j < 4; j++) {
                    simdgroup_float8x8 b;
                    simdgroup_load(b, tile + j * 8 * ATT_LD + dd, ATT_LD, ulong2(0, 0), true);
                    simdgroup_multiply_accumulate(s[j], a, b, s[j]);
                }
            }
        }
        float bmax = -INFINITY;
        #pragma clang loop unroll(full)
        for (int j = 0; j < 4; j++) {
            #pragma clang loop unroll(full)
            for (int e = 0; e < 2; e++) {
                const int kj = int(kb) + j * 8 + int(c0) + e;
                bool valid = kj < int(len);
                if (hw > 0) valid = valid && abs(qi - kj) <= int(hw);
                const float v = valid ? s[j].thread_elements()[e] * p.scale : -INFINITY;
                s[j].thread_elements()[e] = v;
                bmax = max(bmax, v);
            }
        }
        bmax = max(bmax, simd_shuffle_xor(bmax, 1));
        bmax = max(bmax, simd_shuffle_xor(bmax, 8));
        const float mNew = max(m, bmax);
        float alpha = 1.0f;
        float sum = 0.0f;
        if (mNew == -INFINITY) {
            #pragma clang loop unroll(full)
            for (int j = 0; j < 4; j++) s[j] = simdgroup_float8x8(0.0f);
        } else {
            alpha = precise::exp(m - mNew);
            #pragma clang loop unroll(full)
            for (int j = 0; j < 4; j++) {
                #pragma clang loop unroll(full)
                for (int e = 0; e < 2; e++) {
                    const float v = precise::exp(s[j].thread_elements()[e] - mNew);
                    s[j].thread_elements()[e] = v;
                    sum += v;
                }
            }
        }
        sum += simd_shuffle_xor(sum, 1);
        sum += simd_shuffle_xor(sum, 8);
        l = l * alpha + sum;
        m = mNew;

        if (!simd_all(alpha == 1.0f)) {
            #pragma clang loop unroll(full)
            for (int c = 0; c < ATT_DS / 8; c++) {
                o[c].thread_elements()[0] *= alpha;
                o[c].thread_elements()[1] *= alpha;
            }
        }
        #pragma clang loop unroll(full)
        for (int dc = 0; dc < ATT_DS; dc += ATT_DC) {
            threadgroup_barrier(mem_flags::mem_threadgroup);
            stage_tile(tile, vBase + kb * p.kvStride + dc, p.kvStride, tid, threads);
            threadgroup_barrier(mem_flags::mem_threadgroup);
            #pragma clang loop unroll(full)
            for (int j = 0; j < 4; j++) {
                #pragma clang loop unroll(full)
                for (int dd = 0; dd < ATT_DC; dd += 8) {
                    simdgroup_float8x8 vm;
                    simdgroup_load(vm, tile + j * 8 * ATT_LD + dd, ATT_LD);
                    const int c = (dc + dd) / 8;
                    simdgroup_multiply_accumulate(o[c], s[j], vm, o[c]);
                }
            }
        }
    }

    if (qRow0 + r >= len) return;
    const float inv = l > 0.0f ? 1.0f / l : 0.0f;
    device float* oRow = O + (w.seqStart + qRow0 + r) * p.oStride + h * hd + d0 + c0;
    #pragma clang loop unroll(full)
    for (int c = 0; c < ATT_DS / 8; c++) {
        *(device float2*)(oRow + c * 8) = float2(o[c].thread_elements()[0], o[c].thread_elements()[1]) * inv;
    }
}

#define ATTENTION_VARIANT(NAME, DS) \
    template [[host_name(NAME)]] kernel void attention_kernel<DS>( \
        device const float*, device const float*, device const float*, device float*, \
        device const AttentionWork*, constant AttentionParams&, threadgroup float*, uint3, uint, uint, uint);

ATTENTION_VARIANT("attention_fwd", 256)
ATTENTION_VARIANT("attention_fwd_hd512", 512)
ATTENTION_VARIANT("attention_fwd_ds128", 128)

constant int VIS_QUERIES = 64;
constant int VIS_THREADS = VIS_QUERIES / 8 * 32;
constant int VIS_KT_LD = ATT_KEYS + 4;
constant int VIS_KT_FLOATS = ATT_DC * VIS_KT_LD;
constant int VIS_STAGE_FLOAT4S_PER_THREAD = ATT_KEYS * ATT_DC / 4 / VIS_THREADS;

kernel void attention_vision(device const float* Q [[buffer(0)]],
                             device const float* K [[buffer(1)]],
                             device const float* V [[buffer(2)]],
                             device float* O [[buffer(3)]],
                             device const AttentionWork* work [[buffer(4)]],
                             constant AttentionParams& p [[buffer(5)]],
                             threadgroup float* tile [[threadgroup(0)]],
                             uint3 tgid [[threadgroup_position_in_grid]],
                             uint tid [[thread_index_in_threadgroup]],
                             uint sgid [[simdgroup_index_in_threadgroup]],
                             uint lane [[thread_index_in_simdgroup]]) {
    threadgroup float* kTile = tile;
    threadgroup float* vTile = tile + VIS_KT_FLOATS;
    const AttentionWork w = work[tgid.x];
    const uint h = tgid.y;
    const uint len = w.seqLen;
    const uint qRow0 = w.q0 + sgid * 8;
    device const float* qBase = Q + (w.seqStart + qRow0) * p.qStride + h * ATT_DC;
    device const float* kBase = K + w.seqStart * p.kvStride + h * ATT_DC;
    device const float* vBase = V + w.seqStart * p.kvStride + h * ATT_DC;

    simdgroup_float8x8 q[ATT_DC / 8];
    simdgroup_float8x8 o[ATT_DC / 8];
    #pragma clang loop unroll(full)
    for (int c = 0; c < ATT_DC / 8; c++) {
        simdgroup_load(q[c], qBase + c * 8, p.qStride);
        o[c] = simdgroup_float8x8(0.0f);
    }
    const uint c0 = (lane & 1) * 2 + ((lane >> 3) & 1) * 4;
    float m = -INFINITY;
    float l = 0.0f;

    for (uint kb = 0; kb < len; kb += ATT_KEYS) {
        threadgroup_barrier(mem_flags::mem_threadgroup);
        #pragma clang loop unroll(full)
        for (int i = 0; i < VIS_STAGE_FLOAT4S_PER_THREAD; i++) {
            const uint u = tid + i * VIS_THREADS;
            const uint key = u / (ATT_DC / 4), d = u % (ATT_DC / 4) * 4;
            const float4 kv = *(device const float4*)(kBase + (kb + key) * p.kvStride + d);
            const float4 vv = *(device const float4*)(vBase + (kb + key) * p.kvStride + d);
            kTile[(d + 0) * VIS_KT_LD + key] = kv.x;
            kTile[(d + 1) * VIS_KT_LD + key] = kv.y;
            kTile[(d + 2) * VIS_KT_LD + key] = kv.z;
            kTile[(d + 3) * VIS_KT_LD + key] = kv.w;
            threadgroup float* vDst = vTile + key * ATT_LD + d;
            vDst[0] = vv.x; vDst[1] = vv.y; vDst[2] = vv.z; vDst[3] = vv.w;
        }
        threadgroup_barrier(mem_flags::mem_threadgroup);

        simdgroup_float8x8 s[ATT_KEYS / 8];
        #pragma clang loop unroll(full)
        for (int j = 0; j < ATT_KEYS / 8; j++) s[j] = simdgroup_float8x8(0.0f);
        #pragma clang loop unroll(full)
        for (int dd = 0; dd < ATT_DC / 8; dd++) {
            #pragma clang loop unroll(full)
            for (int j = 0; j < ATT_KEYS / 8; j++) {
                simdgroup_float8x8 b;
                simdgroup_load(b, kTile + dd * 8 * VIS_KT_LD + j * 8, VIS_KT_LD);
                simdgroup_multiply_accumulate(s[j], q[dd], b, s[j]);
            }
        }
        float bmax = -INFINITY;
        #pragma clang loop unroll(full)
        for (int j = 0; j < ATT_KEYS / 8; j++) {
            #pragma clang loop unroll(full)
            for (int e = 0; e < 2; e++) {
                const int kj = int(kb) + j * 8 + int(c0) + e;
                const float v = kj < int(len) ? s[j].thread_elements()[e] * p.scale : -INFINITY;
                s[j].thread_elements()[e] = v;
                bmax = max(bmax, v);
            }
        }
        bmax = max(bmax, simd_shuffle_xor(bmax, 1));
        bmax = max(bmax, simd_shuffle_xor(bmax, 8));
        const float mNew = max(m, bmax);
        const float alpha = precise::exp(m - mNew);
        float sum = 0.0f;
        #pragma clang loop unroll(full)
        for (int j = 0; j < ATT_KEYS / 8; j++) {
            #pragma clang loop unroll(full)
            for (int e = 0; e < 2; e++) {
                const float v = precise::exp(s[j].thread_elements()[e] - mNew);
                s[j].thread_elements()[e] = v;
                sum += v;
            }
        }
        sum += simd_shuffle_xor(sum, 1);
        sum += simd_shuffle_xor(sum, 8);
        l = l * alpha + sum;
        m = mNew;
        if (!simd_all(alpha == 1.0f)) {
            #pragma clang loop unroll(full)
            for (int c = 0; c < ATT_DC / 8; c++) {
                o[c].thread_elements()[0] *= alpha;
                o[c].thread_elements()[1] *= alpha;
            }
        }
        #pragma clang loop unroll(full)
        for (int j = 0; j < ATT_KEYS / 8; j++) {
            #pragma clang loop unroll(full)
            for (int dd = 0; dd < ATT_DC / 8; dd++) {
                simdgroup_float8x8 vm;
                simdgroup_load(vm, vTile + j * 8 * ATT_LD + dd * 8, ATT_LD);
                simdgroup_multiply_accumulate(o[dd], s[j], vm, o[dd]);
            }
        }
    }

    const uint r = ((lane >> 1) & 3) | ((lane >> 4) << 2);
    if (qRow0 + r >= len) return;
    const float inv = 1.0f / l;
    device float* oRow = O + (w.seqStart + qRow0 + r) * p.oStride + h * ATT_DC + c0;
    #pragma clang loop unroll(full)
    for (int c = 0; c < ATT_DC / 8; c++) {
        *(device float2*)(oRow + c * 8) = float2(o[c].thread_elements()[0], o[c].thread_elements()[1]) * inv;
    }
}

"""#,
"Audio.metal": #"""
// Copyright 2026 Peter Marelas
// SPDX-License-Identifier: Apache-2.0
// The gemma4a audio tower: subsampling convolutions, clipped-linear glue, local attention with
// relative keys, the GLU and depthwise convolution module. Written for correctness against the
// CPU reference first; the GEMMs and norms come from GEMM.metal and Elementwise.metal.

struct AudioConvParams {
    uint inTime;
    uint inFreq;
    uint inChannels;
    uint outTime;
    uint outFreq;
    uint outChannels;
    uint inOffset;
    uint outOffset;
    float eps;
};

struct AudioElementwiseParams {
    uint rows;
    uint width;
    uint perDimWidth;
    float scale;
    float lo;
    float hi;
};

struct AudioRowsParams {
    uint rows;
    uint width;
    uint taps;
    float scale;
};

struct AudioAttentionParams {
    uint tokens;
    uint heads;
    uint headDim;
    uint window;
    float softcap;
};

// One threadgroup per output position (freq, time) of a 3x3 stride-2 pad-1 convolution over
// `x[(inOffset + t) * inFreq + f][inChannels]`, one thread per output channel, followed by a
// LayerNorm over the channels, the norm weight and ReLU. ggml runs the im2col in fp16, so every
// input value is rounded to half first. The kernel is `[outChannels][inChannels][3][3]` fp32.
// The 1->128 layer runs here; the 128->32 layer runs as the implicit GEMM below.
kernel void audio_subsample(device const float* x [[buffer(0)]],
                            device const float* w [[buffer(1)]],
                            device const float* norm [[buffer(2)]],
                            device float* out [[buffer(3)]],
                            constant AudioConvParams& p [[buffer(4)]],
                            uint2 group [[threadgroup_position_in_grid]],
                            uint oc [[thread_index_in_threadgroup]],
                            uint lane [[thread_index_in_simdgroup]],
                            uint sgid [[simdgroup_index_in_threadgroup]],
                            uint simdgroups [[simdgroups_per_threadgroup]]) {
    threadgroup float partial[32];
    const uint of = group.x, ot = group.y;
    float acc = 0.0f;
    if (oc < p.outChannels) {
        device const float* wk = w + oc * p.inChannels * 9;
        for (uint kh = 0; kh < 3; kh++) {
            const int t = int(2 * ot + kh) - 1;
            if (t < 0 || t >= int(p.inTime)) continue;
            for (uint kw = 0; kw < 3; kw++) {
                const int f = int(2 * of + kw) - 1;
                if (f < 0 || f >= int(p.inFreq)) continue;
                device const float* xi = x + ((p.inOffset + uint(t)) * p.inFreq + uint(f)) * p.inChannels;
                for (uint ic = 0; ic < p.inChannels; ic++) {
                    acc += float(half(xi[ic])) * wk[ic * 9 + kh * 3 + kw];
                }
            }
        }
    }
    float s = simd_sum(oc < p.outChannels ? acc : 0.0f);
    if (lane == 0) partial[sgid] = s;
    threadgroup_barrier(mem_flags::mem_threadgroup);
    float mean = 0.0f;
    for (uint i = 0; i < simdgroups; i++) mean += partial[i];
    mean /= float(p.outChannels);
    const float d = acc - mean;
    threadgroup_barrier(mem_flags::mem_threadgroup);
    s = simd_sum(oc < p.outChannels ? d * d : 0.0f);
    if (lane == 0) partial[sgid] = s;
    threadgroup_barrier(mem_flags::mem_threadgroup);
    float variance = 0.0f;
    for (uint i = 0; i < simdgroups; i++) variance += partial[i];
    variance /= float(p.outChannels);
    if (oc >= p.outChannels) return;
    const float scale = 1.0f / precise::sqrt(variance + p.eps);
    out[((p.outOffset + ot) * p.outFreq + of) * p.outChannels + oc] = max(0.0f, d * scale * norm[oc]);
}

// The same convolution as an implicit GEMM for the 128->32 layer: Y[M, 32] = patch[M, K] * W[32, K]^T
// with M the output positions in (time, freq) order and K = 9 * inChannels in (tap, channel) order,
// so each row's K slice for one tap is a contiguous channel run of `x`. The patch tile is gathered
// into threadgroup memory on the fly (fp16-rounded, zero outside the input) instead of an im2col
// buffer, the weight tile is read from the `[outChannels][inChannels][3][3]` layout with a stride-9
// gather, and the LayerNorm, norm weight and ReLU run over the staged output tile, one output row
// per simdgroup pass. BN is fixed at 32: a tile holds whole output rows, which the norm needs.
template <int BM, int BK, int SG>
kernel void audio_subsample_gemm(device const float* x [[buffer(0)]],
                                 device const float* w [[buffer(1)]],
                                 device const float* norm [[buffer(2)]],
                                 device float* out [[buffer(3)]],
                                 constant AudioConvParams& p [[buffer(4)]],
                                 uint tg [[threadgroup_position_in_grid]],
                                 uint tid [[thread_index_in_threadgroup]],
                                 uint sgid [[simdgroup_index_in_threadgroup]],
                                 uint lane [[thread_index_in_simdgroup]]) {
    constexpr int BN = 32;
    constexpr int LD = BK + 4;
    constexpr int THREADS = SG * 32;
    constexpr int SN = BN / SG;
    constexpr int TM = BM / 8, TN = SN / 8;
    constexpr int OUT_LD = BN + 4;
    constexpr int STAGE = (BM + BN) * LD;
    static_assert(STAGE >= BM * OUT_LD, "the output tile must fit the staging buffer");
    threadgroup float stage[STAGE];
    threadgroup float* Xs = stage;
    threadgroup float* Ws = stage + BM * LD;

    const uint M = p.outTime * p.outFreq;
    const uint K = 9 * p.inChannels;
    const uint m0 = tg * BM;

    simdgroup_float8x8 acc[TM][TN];
    #pragma clang loop unroll(full)
    for (int i = 0; i < TM; i++)
        #pragma clang loop unroll(full)
        for (int j = 0; j < TN; j++) acc[i][j] = simdgroup_float8x8(0.0f);

    for (uint k0 = 0; k0 < K; k0 += BK) {
        threadgroup_barrier(mem_flags::mem_threadgroup);
        for (uint u = tid; u < BM * BK / 4; u += THREADS) {
            const uint row = u / (BK / 4), c4 = u % (BK / 4);
            const uint m = m0 + row, k = k0 + c4 * 4;
            const uint ot = m / p.outFreq, of = m % p.outFreq;
            const uint tap = k / p.inChannels, ic = k % p.inChannels;
            const int t = int(2 * ot + tap / 3) - 1, f = int(2 * of + tap % 3) - 1;
            float4 v = 0.0f;
            if (m < M && t >= 0 && t < int(p.inTime) && f >= 0 && f < int(p.inFreq)) {
                const float4 raw = *(device const float4*)(x + ((p.inOffset + uint(t)) * p.inFreq + uint(f)) * p.inChannels + ic);
                v = float4(half4(raw));
            }
            threadgroup float* dst = Xs + row * LD + c4 * 4;
            dst[0] = v.x; dst[1] = v.y; dst[2] = v.z; dst[3] = v.w;
        }
        for (uint u = tid; u < BN * BK / 8; u += THREADS) {
            const uint row = u / (BK / 8), c8 = u % (BK / 8);
            const uint k = k0 + c8 * 8;
            device const float* src = w + (row * p.inChannels + k % p.inChannels) * 9 + k / p.inChannels;
            threadgroup float* dst = Ws + row * LD + c8 * 8;
            #pragma clang loop unroll(full)
            for (int i = 0; i < 8; i++) dst[i] = src[i * 9];
        }
        threadgroup_barrier(mem_flags::mem_threadgroup);
        #pragma clang loop unroll(full)
        for (int kk = 0; kk < BK; kk += 8) {
            simdgroup_float8x8 a[TM];
            simdgroup_float8x8 b[TN];
            #pragma clang loop unroll(full)
            for (int i = 0; i < TM; i++)
                simdgroup_load(a[i], Xs + i * 8 * LD + kk, LD);
            #pragma clang loop unroll(full)
            for (int j = 0; j < TN; j++)
                simdgroup_load(b[j], Ws + (sgid * SN + j * 8) * LD + kk, LD, ulong2(0, 0), true);
            #pragma clang loop unroll(full)
            for (int i = 0; i < TM; i++)
                #pragma clang loop unroll(full)
                for (int j = 0; j < TN; j++)
                    simdgroup_multiply_accumulate(acc[i][j], a[i], b[j], acc[i][j]);
        }
    }

    threadgroup_barrier(mem_flags::mem_threadgroup);
    #pragma clang loop unroll(full)
    for (int i = 0; i < TM; i++)
        #pragma clang loop unroll(full)
        for (int j = 0; j < TN; j++)
            simdgroup_store(acc[i][j], stage + i * 8 * OUT_LD + sgid * SN + j * 8, OUT_LD);
    threadgroup_barrier(mem_flags::mem_threadgroup);
    const float nw = norm[lane];
    for (uint row = sgid; row < BM; row += SG) {
        const uint m = m0 + row;
        if (m >= M) break;
        const float v = stage[row * OUT_LD + lane];
        const float mean = simd_sum(v) / float(BN);
        const float d = v - mean;
        const float variance = simd_sum(d * d) / float(BN);
        const float scale = 1.0f / precise::sqrt(variance + p.eps);
        out[(p.outOffset * p.outFreq + m) * BN + lane] = max(0.0f, d * scale * nw);
    }
}

#define AUDIO_SUBSAMPLE_GEMM(SUFFIX, BM, BK, SG) \
    template [[host_name("audio_subsample_gemm_" SUFFIX)]] kernel void audio_subsample_gemm<BM, BK, SG>( \
        device const float*, device const float*, device const float*, device float*, constant AudioConvParams&, uint, uint, uint, uint);

AUDIO_SUBSAMPLE_GEMM("32x32x32_4", 32, 32, 4)

// x = clamp(x * scale * perDim[i % perDimWidth], lo, hi), the per-dimension factor only when perDimWidth > 0.
kernel void audio_elementwise(device float* x [[buffer(0)]],
                              device const float* perDim [[buffer(1)]],
                              constant AudioElementwiseParams& p [[buffer(2)]],
                              uint i [[thread_position_in_grid]]) {
    if (i >= p.rows * p.width) return;
    float v = x[i] * p.scale;
    if (p.perDimWidth > 0) v *= perDim[i % p.perDimWidth];
    x[i] = clamp(v, p.lo, p.hi);
}

kernel void audio_silu(device float* x [[buffer(0)]],
                       constant AudioRowsParams& p [[buffer(1)]],
                       uint i [[thread_position_in_grid]]) {
    if (i >= p.rows * p.width) return;
    const float v = x[i];
    x[i] = v / (1.0f + exp(-v));
}

// x += scale * t
kernel void audio_add(device float* x [[buffer(0)]],
                      device const float* t [[buffer(1)]],
                      constant AudioRowsParams& p [[buffer(2)]],
                      uint i [[thread_position_in_grid]]) {
    if (i >= p.rows * p.width) return;
    x[i] += p.scale * t[i];
}

kernel void audio_add_bias(device float* x [[buffer(0)]],
                           device const float* bias [[buffer(1)]],
                           constant AudioRowsParams& p [[buffer(2)]],
                           uint i [[thread_position_in_grid]]) {
    if (i >= p.rows * p.width) return;
    x[i] += bias[i % p.width];
}

// out[t][i] = x[t][i] * sigmoid(x[t][width + i]) over rows of 2 * width.
kernel void audio_glu(device const float* x [[buffer(0)]],
                      device float* out [[buffer(1)]],
                      constant AudioRowsParams& p [[buffer(2)]],
                      uint i [[thread_position_in_grid]]) {
    if (i >= p.rows * p.width) return;
    const uint t = i / p.width, c = i % p.width;
    const float gate = x[t * 2 * p.width + p.width + c];
    out[i] = x[t * 2 * p.width + c] * (1.0f / (1.0f + exp(-gate)));
}

// Causal depthwise convolution within a chunk: out[t][c] = sum_k x[t + k - (kernel - 1)][c] * w[c][k],
// with frames before the chunk's first row counting as zero.
kernel void audio_dwconv(device const float* x [[buffer(0)]],
                         device const float* w [[buffer(1)]],
                         device const uint* chunkStart [[buffer(2)]],
                         device float* out [[buffer(3)]],
                         constant AudioRowsParams& p [[buffer(4)]],
                         uint i [[thread_position_in_grid]]) {
    if (i >= p.rows * p.width) return;
    const uint t = i / p.width, c = i % p.width;
    const int first = int(chunkStart[t]);
    float s = 0.0f;
    for (uint k = 0; k < p.taps; k++) {
        const int src = int(t + k) - int(p.taps - 1);
        if (src >= first) s += x[src * p.width + c] * w[c * p.taps + k];
    }
    out[i] = s;
}

// Local causal attention with relative keys: query t attends to keys t - 11 ... t of its chunk, and the key at
// distance d scores q . k + q . rel[d], soft-capped as softcap * tanh(s / softcap).
// One simdgroup per (query, head): lane l owns dims 4l .. 4l + 3, every score is a simd reduction over the
// lanes, and the softmax runs redundantly on all 32 lanes. The threadgroup holds 8 consecutive queries of
// one head, so their overlapping keys share the cache lines.
#define AUDIO_ATTENTION_WINDOW 12
#define AUDIO_HEAD_DIM 128

kernel void audio_attention(device const float* q [[buffer(0)]],
                            device const float* k [[buffer(1)]],
                            device const float* v [[buffer(2)]],
                            device const float* rel [[buffer(3)]],
                            device const uint* chunkStart [[buffer(4)]],
                            device float* out [[buffer(5)]],
                            constant AudioAttentionParams& p [[buffer(6)]],
                            uint2 gid [[thread_position_in_grid]],
                            uint lane [[thread_index_in_simdgroup]]) {
    const uint t = gid.x / 32, h = gid.y;
    if (t >= p.tokens || h >= p.heads) return;
    const uint width = p.heads * AUDIO_HEAD_DIM;
    const uint first = max(chunkStart[t], t + 1 - min(uint(AUDIO_ATTENTION_WINDOW), t + 1));
    const uint count = t + 1 - first;
    const uint col = h * AUDIO_HEAD_DIM + lane * 4;
    const float4 qt = *(device const float4*)(q + t * width + col);
    // scores[n] is the key at distance n; the loops walk n downwards so the sums run over keys in
    // increasing order, as the CPU reference does.
    float scores[AUDIO_ATTENTION_WINDOW];
#pragma clang loop unroll(full)
    for (int n = AUDIO_ATTENTION_WINDOW - 1; n >= 0; n--) {
        float partial = 0.0f;
        if (uint(n) < count) {
            const float4 kj = *(device const float4*)(k + (t - n) * width + col);
            const float4 rn = *(device const float4*)(rel + n * width + col);
            partial = dot(qt, kj) + dot(qt, rn);
        }
        scores[n] = simd_sum(partial);
    }
    float maxScore = -INFINITY;
#pragma clang loop unroll(full)
    for (int n = AUDIO_ATTENTION_WINDOW - 1; n >= 0; n--) {
        if (uint(n) < count) {
            scores[n] = p.softcap * precise::tanh(scores[n] / p.softcap);
            maxScore = max(maxScore, scores[n]);
        }
    }
    float sum = 0.0f;
#pragma clang loop unroll(full)
    for (int n = AUDIO_ATTENTION_WINDOW - 1; n >= 0; n--) {
        if (uint(n) < count) {
            scores[n] = exp(scores[n] - maxScore);
            sum += scores[n];
        }
    }
    float4 o = float4(0.0f);
#pragma clang loop unroll(full)
    for (int n = AUDIO_ATTENTION_WINDOW - 1; n >= 0; n--) {
        if (uint(n) < count) {
            const float w = scores[n] / sum;
            o += w * *(device const float4*)(v + (t - n) * width + col);
        }
    }
    *(device float4*)(out + t * width + col) = o;
}

"""#,
"Common.metal": #"""
// Copyright 2026 Peter Marelas
// SPDX-License-Identifier: Apache-2.0
#include <metal_stdlib>
#include <metal_simdgroup_matrix>
using namespace metal;

// Shared helpers for every GemmaEmbed kernel. Storage types (Q8_0, BF16, F16) are widened to
// fp32 at load time; every arithmetic operation runs in fp32.

inline float bf16_to_float(ushort b) {
    return as_type<float>(uint(b) << 16);
}

inline float f16_to_float(ushort h) {
    return float(as_type<half>(h));
}

inline float gelu_tanh(float x) {
    const float c = 0.79788456080286535587989211986876f;
    return 0.5f * x * (1.0f + precise::tanh(c * x * (1.0f + 0.044715f * x * x)));
}

inline float gelu_quick(float x) {
    return x / (1.0f + precise::exp(-1.702f * x));
}

// Q8_0 layout: blocks of 32 along the contiguous dimension, each block is an fp16 scale
// followed by 32 int8 values (34 bytes). A row of K elements occupies K / 32 * 34 bytes.
constant uint Q8_BLOCK_BYTES = 34;

struct RowParams {
    uint rows;
    uint width;
    uint inStride;
    uint outStride;
    float eps;
    float preScale;
    uint hasWeight;
};

struct RopeParams {
    uint tokens;
    uint heads;
    uint headDim;
    uint stride;
    uint tableStride;
};

struct EmbedParams {
    uint tokens;
    uint paddedRows;
    uint width;
    float scale;
};

struct GemmParams {
    uint M;
    uint N;
    uint K;
    uint weightRowBytes;
};

struct AttentionParams {
    uint heads;
    uint kvHeads;
    uint headDim;
    uint qStride;
    uint kvStride;
    uint oStride;
    uint halfWindow;
    uint queriesPerGroup;
    float scale;
};

struct AttentionWork {
    uint seqStart;
    uint seqLen;
    uint q0;
};

struct PoolParams {
    uint width;
    uint stride;
};

struct Sequence {
    uint start;
    uint length;
};

struct PositionParams {
    uint rows;
    uint width;
    uint positionCount;
};

// One image of a vision batch: where its patch rows and token rows start, and its patch grid.
struct PoolGrid {
    uint patchStart;
    uint tokenStart;
    uint gridX;
    uint gridY;
};

struct PoolPatchParams {
    uint width;
    uint merge;
    float scale;
};

"""#,
"Elementwise.metal": #"""
// Copyright 2026 Peter Marelas
// SPDX-License-Identifier: Apache-2.0
// Token embedding gather, norms, RoPE, activations, residual updates and pooling.

// Floats a simdgroup covers when each of its 32 lanes moves one float4.
constant int SIMD_FLOAT4_SPAN = 32 * 4;

kernel void embed_q8(device const uchar* table [[buffer(0)]],
                     device const int* tokens [[buffer(1)]],
                     device float* out [[buffer(2)]],
                     constant EmbedParams& p [[buffer(3)]],
                     device const float* vectors [[buffer(4)]],
                     device float* residual [[buffer(5)]],
                     uint2 gid [[thread_position_in_grid]]) {
    const uint t = gid.y;
    const uint block = gid.x;
    if (t >= p.paddedRows || block * 32 >= p.width) return;
    const uint offset = t * p.width + block * 32;
    device float* o = out + offset;
    device float* r = residual + offset;
    if (t >= p.tokens) {
        for (uint j = 0; j < 32; j++) { o[j] = 0.0f; r[j] = 0.0f; }
        return;
    }
    const int id = tokens[t];
    if (id < 0) {
        device const float* v = vectors + uint(-(id + 1)) * p.width + block * 32;
        for (uint j = 0; j < 32; j++) { const float e = v[j]; o[j] = e; r[j] = e; }
        return;
    }
    const uint rowBytes = p.width / 32 * Q8_BLOCK_BYTES;
    device const uchar* b = table + uint(id) * rowBytes + block * Q8_BLOCK_BYTES;
    const float scale = f16_to_float(ushort(b[0]) | (ushort(b[1]) << 8)) * p.scale;
    for (uint j = 0; j < 32; j++) { const float e = scale * float(as_type<char>(b[2 + j])); o[j] = e; r[j] = e; }
}

// RMS norm of each row: out = x * preScale / sqrt(mean((x * preScale)^2) + eps) * w.
kernel void rmsnorm_rows(device const float* x [[buffer(0)]],
                         device float* out [[buffer(1)]],
                         device const float* weight [[buffer(2)]],
                         constant RowParams& p [[buffer(3)]],
                         uint tid [[thread_position_in_grid]],
                         uint lane [[thread_index_in_simdgroup]]) {
    const uint row = tid / 32;
    if (row >= p.rows) return;
    device const float* xr = x + row * p.inStride;
    device float* o = out + row * p.outStride;
    float ss = 0.0f;
    if (p.width % SIMD_FLOAT4_SPAN == 0) {
        for (uint i = lane * 4; i < p.width; i += SIMD_FLOAT4_SPAN) {
            const float4 v = *(device const float4*)(xr + i) * p.preScale;
            ss += v.x * v.x;
            ss += v.y * v.y;
            ss += v.z * v.z;
            ss += v.w * v.w;
        }
        ss = simd_sum(ss);
        const float inv = 1.0f / precise::sqrt(ss / float(p.width) + p.eps);
        for (uint i = lane * 4; i < p.width; i += SIMD_FLOAT4_SPAN) {
            const float4 v = *(device const float4*)(xr + i) * p.preScale * inv;
            *(device float4*)(o + i) = p.hasWeight ? v * *(device const float4*)(weight + i) : v;
        }
        return;
    }
    for (uint i = lane; i < p.width; i += 32) {
        const float v = xr[i] * p.preScale;
        ss += v * v;
    }
    ss = simd_sum(ss);
    const float inv = 1.0f / precise::sqrt(ss / float(p.width) + p.eps);
    for (uint i = lane; i < p.width; i += 32) {
        const float v = xr[i] * p.preScale * inv;
        o[i] = p.hasWeight ? v * weight[i] : v;
    }
}

// NeoX RoPE in place on [tokens][heads][headDim] with a precomputed cos/sin table
// indexed by [position][pair] (two floats per entry).
kernel void rope_neox(device float* x [[buffer(0)]],
                      device const int* positions [[buffer(1)]],
                      device const float* table [[buffer(2)]],
                      constant RopeParams& p [[buffer(3)]],
                      uint3 gid [[thread_position_in_grid]]) {
    const uint pair = gid.x;
    const uint head = gid.y;
    const uint t = gid.z;
    const uint halfDim = p.headDim / 2;
    if (pair >= halfDim || head >= p.heads || t >= p.tokens) return;
    device float* v = x + t * p.stride + head * p.headDim;
    device const float* cs = table + (uint(positions[t]) * p.tableStride + pair) * 2;
    const float c = cs[0], s = cs[1];
    const float a = v[pair], b = v[pair + halfDim];
    v[pair] = a * c - b * s;
    v[pair + halfDim] = a * s + b * c;
}

template <int W>
kernel void rmsnorm_rope_kernel(device float* x [[buffer(0)]],
                                device const float* weight [[buffer(1)]],
                                device const int* positions [[buffer(2)]],
                                device const float* table [[buffer(3)]],
                                constant RowParams& n [[buffer(4)]],
                                constant RopeParams& p [[buffer(5)]],
                                uint tid [[thread_position_in_grid]],
                                uint lane [[thread_index_in_simdgroup]]) {
    constexpr int CHUNKS = W / SIMD_FLOAT4_SPAN;
    constexpr int HALF = W / 2;
    static_assert(HALF % SIMD_FLOAT4_SPAN == 0, "a pair's two values must sit in the same lane");
    const uint row = tid / 32;
    if (row >= n.rows) return;
    device float* xr = x + row * W;
    float4 v[CHUNKS];
    float ss = 0.0f;
    for (int j = 0; j < CHUNKS; j++) {
        v[j] = *(device const float4*)(xr + lane * 4 + SIMD_FLOAT4_SPAN * j);
        const float4 u = v[j] * n.preScale;
        ss += u.x * u.x;
        ss += u.y * u.y;
        ss += u.z * u.z;
        ss += u.w * u.w;
    }
    ss = simd_sum(ss);
    const float inv = 1.0f / precise::sqrt(ss / float(W) + n.eps);
    device const float* cs = table + uint(positions[row / p.heads]) * p.tableStride * 2;
    for (int j = 0; j < CHUNKS / 2; j++) {
        const uint pair = lane * 4 + SIMD_FLOAT4_SPAN * j;
        const float4 a = v[j] * n.preScale * inv * *(device const float4*)(weight + pair);
        const float4 b = v[j + CHUNKS / 2] * n.preScale * inv * *(device const float4*)(weight + pair + HALF);
        const float4 cs0 = *(device const float4*)(cs + pair * 2);
        const float4 cs1 = *(device const float4*)(cs + pair * 2 + 4);
        const float4 c = float4(cs0.x, cs0.z, cs1.x, cs1.z);
        const float4 s = float4(cs0.y, cs0.w, cs1.y, cs1.w);
        *(device float4*)(xr + pair) = a * c - b * s;
        *(device float4*)(xr + pair + HALF) = a * s + b * c;
    }
}

template [[host_name("rmsnorm_rope_256")]] kernel void rmsnorm_rope_kernel<256>(
    device float*, device const float*, device const int*, device const float*, constant RowParams&, constant RopeParams&, uint, uint);
template [[host_name("rmsnorm_rope_512")]] kernel void rmsnorm_rope_kernel<512>(
    device float*, device const float*, device const int*, device const float*, constant RowParams&, constant RopeParams&, uint, uint);

// 2D NeoX RoPE in place on [tokens][heads][headDim]: the first half of every head rotates by the
// patch column px, the second half by the patch row py, each as a NeoX rotation of headDim / 2
// dims. The table holds headDim / 4 pairs per position.
kernel void rope_2d(device float* x [[buffer(0)]],
                    device const int* px [[buffer(1)]],
                    device const int* py [[buffer(2)]],
                    device const float* table [[buffer(3)]],
                    constant RopeParams& p [[buffer(4)]],
                    uint3 gid [[thread_position_in_grid]]) {
    const uint quarter = p.headDim / 4;
    const uint pair = gid.x % quarter;
    const uint axis = gid.x / quarter;
    const uint head = gid.y;
    const uint t = gid.z;
    if (axis >= 2 || head >= p.heads || t >= p.tokens) return;
    device float* v = x + t * p.stride + head * p.headDim + axis * (p.headDim / 2);
    const int pos = axis == 0 ? px[t] : py[t];
    device const float* cs = table + (uint(pos) * p.tableStride + pair) * 2;
    const float c = cs[0], s = cs[1];
    const float a = v[pair], b = v[pair + quarter];
    v[pair] = a * c - b * s;
    v[pair + quarter] = a * s + b * c;
}

kernel void rmsnorm_rope_2d_64(device float* x [[buffer(0)]],
                               device const float* weight [[buffer(1)]],
                               device const int* px [[buffer(2)]],
                               device const int* py [[buffer(3)]],
                               device const float* table [[buffer(4)]],
                               constant RowParams& n [[buffer(5)]],
                               constant RopeParams& p [[buffer(6)]],
                               uint tid [[thread_position_in_grid]],
                               uint lane [[thread_index_in_simdgroup]]) {
    constexpr uint W = 64, QUARTER = W / 4;
    const uint row = tid / 32;
    if (row >= n.rows) return;
    device float* xr = x + row * W;
    const float x0 = xr[lane], x1 = xr[lane + 32];
    float ss = 0.0f;
    const float v0 = x0 * n.preScale;
    ss += v0 * v0;
    const float v1 = x1 * n.preScale;
    ss += v1 * v1;
    ss = simd_sum(ss);
    const float inv = 1.0f / precise::sqrt(ss / float(W) + n.eps);
    const float u0 = x0 * n.preScale * inv * weight[lane];
    const float u1 = x1 * n.preScale * inv * weight[lane + 32];
    const float w0 = simd_shuffle_xor(u0, QUARTER);
    const float w1 = simd_shuffle_xor(u1, QUARTER);
    const uint t = row / p.heads;
    const uint pair = lane % QUARTER;
    const float2 c0 = *(device const float2*)(table + (uint(px[t]) * p.tableStride + pair) * 2);
    const float2 c1 = *(device const float2*)(table + (uint(py[t]) * p.tableStride + pair) * 2);
    if (lane < QUARTER) {
        xr[lane] = u0 * c0.x - w0 * c0.y;
        xr[lane + 32] = u1 * c1.x - w1 * c1.y;
    } else {
        xr[lane] = w0 * c0.y + u0 * c0.x;
        xr[lane + 32] = w1 * c1.y + u1 * c1.x;
    }
}

// h[t] = (h[t] + table[px[t]]) + table[positionCount + py[t]]: the learned column and row
// embeddings of every patch, added in the CPU reference's order.
kernel void add_position_rows(device float* h [[buffer(0)]],
                              device const float* table [[buffer(1)]],
                              device const int* px [[buffer(2)]],
                              device const int* py [[buffer(3)]],
                              constant PositionParams& p [[buffer(4)]],
                              uint2 gid [[thread_position_in_grid]]) {
    const uint i = gid.x;
    const uint t = gid.y;
    if (i >= p.width || t >= p.rows) return;
    device float* row = h + t * p.width;
    row[i] = (row[i] + table[uint(px[t]) * p.width + i]) + table[(p.positionCount + uint(py[t])) * p.width + i];
}

// Merges every merge x merge window of an image's patch grid into one token row:
// pooled[tokenStart + oy * gx / merge + ox] = sum of the window's patch rows * scale, where scale
// is sqrt(width) / merge^2. Grid z selects the image, y the token, x the channel.
kernel void pool_patches(device const float* x [[buffer(0)]],
                         device const PoolGrid* grids [[buffer(1)]],
                         device float* pooled [[buffer(2)]],
                         constant PoolPatchParams& p [[buffer(3)]],
                         uint3 gid [[thread_position_in_grid]]) {
    const PoolGrid g = grids[gid.z];
    const uint m = p.merge;
    const uint tx = g.gridX / m;
    const uint token = gid.y;
    const uint i = gid.x;
    if (i >= p.width || token >= tx * (g.gridY / m)) return;
    const uint ox = token % tx, oy = token / tx;
    float acc = 0.0f;
    for (uint ky = 0; ky < m; ky++)
        for (uint kx = 0; kx < m; kx++)
            acc += x[(g.patchStart + (oy * m + ky) * g.gridX + ox * m + kx) * p.width + i];
    pooled[(g.tokenStart + token) * p.width + i] = acc * p.scale;
}

// pooled[s] = mean over the sequence's rows of x. One threadgroup per sequence.
kernel void mean_pool(device const float* x [[buffer(0)]],
                      device const Sequence* seqs [[buffer(1)]],
                      device float* pooled [[buffer(2)]],
                      constant PoolParams& p [[buffer(3)]],
                      uint s [[threadgroup_position_in_grid]],
                      uint tid [[thread_position_in_threadgroup]],
                      uint tgSize [[threads_per_threadgroup]]) {
    const Sequence seq = seqs[s];
    for (uint c = tid; c < p.width; c += tgSize) {
        float acc = 0.0f;
        for (uint r = 0; r < seq.length; r++) acc += x[(seq.start + r) * p.stride + c];
        pooled[s * p.width + c] = acc / float(seq.length);
    }
}

// x = (x + rmsnorm(t) * w) * scale, one simdgroup per row. Fuses the post-norm of a block
// output with its residual add.
kernel void rmsnorm_residual(device float* x [[buffer(0)]],
                             device const float* t [[buffer(1)]],
                             device const float* weight [[buffer(2)]],
                             constant RowParams& p [[buffer(3)]],
                             uint tid [[thread_position_in_grid]],
                             uint lane [[thread_index_in_simdgroup]]) {
    const uint row = tid / 32;
    if (row >= p.rows) return;
    device const float* tr = t + row * p.inStride;
    device float* xr = x + row * p.outStride;
    float ss = 0.0f;
    if (p.width % SIMD_FLOAT4_SPAN == 0) {
        for (uint i = lane * 4; i < p.width; i += SIMD_FLOAT4_SPAN) {
            const float4 v = *(device const float4*)(tr + i);
            ss += v.x * v.x;
            ss += v.y * v.y;
            ss += v.z * v.z;
            ss += v.w * v.w;
        }
        ss = simd_sum(ss);
        const float inv = 1.0f / precise::sqrt(ss / float(p.width) + p.eps);
        for (uint i = lane * 4; i < p.width; i += SIMD_FLOAT4_SPAN) {
            device float4* xo = (device float4*)(xr + i);
            *xo = (*xo + *(device const float4*)(tr + i) * inv * *(device const float4*)(weight + i)) * p.preScale;
        }
        return;
    }
    for (uint i = lane; i < p.width; i += 32) {
        const float v = tr[i];
        ss += v * v;
    }
    ss = simd_sum(ss);
    const float inv = 1.0f / precise::sqrt(ss / float(p.width) + p.eps);
    for (uint i = lane; i < p.width; i += 32) {
        xr[i] = (xr[i] + tr[i] * inv * weight[i]) * p.preScale;
    }
}


template <int W>
kernel void rmsnorm_residual_norm_kernel(device float* x [[buffer(0)]],
                                         device const float* t [[buffer(1)]],
                                         device const float* weight [[buffer(2)]],
                                         constant RowParams& r [[buffer(3)]],
                                         device float* out [[buffer(4)]],
                                         device const float* outWeight [[buffer(5)]],
                                         constant RowParams& n [[buffer(6)]],
                                         uint tid [[thread_position_in_grid]],
                                         uint lane [[thread_index_in_simdgroup]]) {
    constexpr int CHUNKS = W / SIMD_FLOAT4_SPAN;
    static_assert(W % SIMD_FLOAT4_SPAN == 0, "rows must take the float4 paths");
    const uint row = tid / 32;
    if (row >= r.rows) return;
    device const float* tr = t + row * W;
    device float* xr = x + row * W;
    device float* o = out + row * W;
    float4 tv[CHUNKS];
    float ss = 0.0f;
#pragma clang loop unroll(full)
    for (int j = 0; j < CHUNKS; j++) {
        tv[j] = *(device const float4*)(tr + lane * 4 + SIMD_FLOAT4_SPAN * j);
        ss += tv[j].x * tv[j].x;
        ss += tv[j].y * tv[j].y;
        ss += tv[j].z * tv[j].z;
        ss += tv[j].w * tv[j].w;
    }
    ss = simd_sum(ss);
    const float inv = 1.0f / precise::sqrt(ss / float(W) + r.eps);
    float4 xv[CHUNKS];
    float ss2 = 0.0f;
#pragma clang loop unroll(full)
    for (int j = 0; j < CHUNKS; j++) {
        const uint i = lane * 4 + SIMD_FLOAT4_SPAN * j;
        device float4* xo = (device float4*)(xr + i);
        xv[j] = (*xo + tv[j] * inv * *(device const float4*)(weight + i)) * r.preScale;
        *xo = xv[j];
        const float4 v = xv[j] * n.preScale;
        ss2 += v.x * v.x;
        ss2 += v.y * v.y;
        ss2 += v.z * v.z;
        ss2 += v.w * v.w;
    }
    ss2 = simd_sum(ss2);
    const float inv2 = 1.0f / precise::sqrt(ss2 / float(W) + n.eps);
#pragma clang loop unroll(full)
    for (int j = 0; j < CHUNKS; j++) {
        const uint i = lane * 4 + SIMD_FLOAT4_SPAN * j;
        *(device float4*)(o + i) = xv[j] * n.preScale * inv2 * *(device const float4*)(outWeight + i);
    }
}

template [[host_name("rmsnorm_residual_norm_768")]] kernel void rmsnorm_residual_norm_kernel<768>(
    device float*, device const float*, device const float*, constant RowParams&, device float*, device const float*, constant RowParams&, uint, uint);
template [[host_name("rmsnorm_residual_norm_512")]] kernel void rmsnorm_residual_norm_kernel<512>(
    device float*, device const float*, device const float*, constant RowParams&, device float*, device const float*, constant RowParams&, uint, uint);

"""#,
"GEMM.metal": #"""
// Copyright 2026 Peter Marelas
// SPDX-License-Identifier: Apache-2.0
// Y[M,N] = X[M,K] * W[N,K]^T with fp32 activations and quantized or bf16 weights.
//
// Every loop over the fragment arrays is fully unrolled so they are indexed with constants and
// stay in registers; a rolled loop puts them in memory.

struct FmtQ8 {
    // Stages 8 consecutive weights of one row starting at column k (k % 8 == 0).
    static inline void load8(device const uchar* w, uint rowBytes, uint row, uint k, thread float* out) {
        device const uchar* b = w + row * rowBytes + (k / 32) * Q8_BLOCK_BYTES;
        const float scale = f16_to_float(ushort(b[0]) | (ushort(b[1]) << 8));
        device const ushort* q = (device const ushort*)(b + 2 + (k % 32));
        for (uint i = 0; i < 4; i++) {
            const ushort v = q[i];
            out[2 * i] = scale * float(as_type<char>(uchar(v & 0xFF)));
            out[2 * i + 1] = scale * float(as_type<char>(uchar(v >> 8)));
        }
    }
};

struct FmtBF16 {
    static inline void load8(device const uchar* w, uint rowBytes, uint row, uint k, thread float* out) {
        const uint4 v = *(device const uint4*)(w + row * rowBytes + k * 2);
        out[0] = bf16_to_float(ushort(v.x & 0xFFFF)); out[1] = bf16_to_float(ushort(v.x >> 16));
        out[2] = bf16_to_float(ushort(v.y & 0xFFFF)); out[3] = bf16_to_float(ushort(v.y >> 16));
        out[4] = bf16_to_float(ushort(v.z & 0xFFFF)); out[5] = bf16_to_float(ushort(v.z >> 16));
        out[6] = bf16_to_float(ushort(v.w & 0xFFFF)); out[7] = bf16_to_float(ushort(v.w >> 16));
    }
};

struct FmtF32 {
    static inline void load8(device const uchar* w, uint rowBytes, uint row, uint k, thread float* out) {
        device const float4* q = (device const float4*)(w + row * rowBytes + k * 4);
        const float4 a = q[0], b = q[1];
        out[0] = a.x; out[1] = a.y; out[2] = a.z; out[3] = a.w;
        out[4] = b.x; out[5] = b.y; out[6] = b.z; out[7] = b.w;
    }
};

struct EpiStore {
    static inline float4 apply(float4 v, device const float* aux, uint index) { return v; }
};

// y = gelu(aux) * y, where aux holds the gate projection at the same index.
struct EpiGeglu {
    static inline float4 apply(float4 v, device const float* aux, uint index) {
        const float4 g = *(device const float4*)(aux + index);
        return float4(gelu_tanh(g.x), gelu_tanh(g.y), gelu_tanh(g.z), gelu_tanh(g.w)) * v;
    }
};

// y = gelu_quick(aux) * y, the vision tower's FFN activation.
struct EpiGegluQuick {
    static inline float4 apply(float4 v, device const float* aux, uint index) {
        const float4 g = *(device const float4*)(aux + index);
        return float4(gelu_quick(g.x), gelu_quick(g.y), gelu_quick(g.z), gelu_quick(g.w)) * v;
    }
};

// y = gelu(y) * aux, where aux holds the per-layer input at the same index.
struct EpiGeluTimes {
    static inline float4 apply(float4 v, device const float* aux, uint index) {
        const float4 a = *(device const float4*)(aux + index);
        return float4(gelu_tanh(v.x), gelu_tanh(v.y), gelu_tanh(v.z), gelu_tanh(v.w)) * a;
    }
};

template <int BM, int BN, int BK>
constexpr int gemm_stage_floats() { return (BM + BN) * (BK + 4); }

template <typename Fmt, typename Epi, int BM, int BN, int BK, int SG>
inline void gemm_tile(device const float* X, device const uchar* W, device float* Y, constant GemmParams& p,
                      device const float* aux, threadgroup float* stage, uint2 tgid, uint tid, uint sgid) {
    constexpr int LD = BK + 4;
    constexpr int THREADS = SG * 32;
    constexpr int SN = BN / SG;
    constexpr int TM = BM / 8, TN = SN / 8;
    constexpr int STAGE = gemm_stage_floats<BM, BN, BK>();
    constexpr int OUT_LD = BN + 4;
    // Output rows staged per pass: the largest power-of-two fraction of BM that fits.
    constexpr int FIT = STAGE / OUT_LD;
    constexpr int PASS_ROWS = FIT >= BM ? BM : (FIT >= BM / 2 ? BM / 2 : (FIT >= BM / 4 ? BM / 4 : BM / 8));
    constexpr int PASSES = BM / PASS_ROWS;
    threadgroup float* Xs = stage;
    threadgroup float* Ws = stage + BM * LD;

    const uint m0 = tgid.y * BM;
    const uint n0 = tgid.x * BN;
    const uint K = p.K;

    simdgroup_float8x8 acc[TM][TN];
    #pragma clang loop unroll(full)
    for (int i = 0; i < TM; i++)
        #pragma clang loop unroll(full)
        for (int j = 0; j < TN; j++) acc[i][j] = simdgroup_float8x8(0.0f);

    for (uint k0 = 0; k0 < K; k0 += BK) {
        threadgroup_barrier(mem_flags::mem_threadgroup);
        for (uint u = tid; u < BM * BK / 4; u += THREADS) {
            const uint row = u / (BK / 4), c4 = u % (BK / 4);
            const float4 v = *(device const float4*)(X + (m0 + row) * K + k0 + c4 * 4);
            threadgroup float* dst = Xs + row * LD + c4 * 4;
            dst[0] = v.x; dst[1] = v.y; dst[2] = v.z; dst[3] = v.w;
        }
        for (uint u = tid; u < BN * BK / 8; u += THREADS) {
            const uint row = u / (BK / 8), c8 = u % (BK / 8);
            float vals[8];
            Fmt::load8(W, p.weightRowBytes, n0 + row, k0 + c8 * 8, vals);
            threadgroup float* dst = Ws + row * LD + c8 * 8;
            for (int i = 0; i < 8; i++) dst[i] = vals[i];
        }
        threadgroup_barrier(mem_flags::mem_threadgroup);
        #pragma clang loop unroll(full)
        for (int kk = 0; kk < BK; kk += 8) {
            simdgroup_float8x8 a[TM];
            simdgroup_float8x8 b[TN];
            #pragma clang loop unroll(full)
            for (int i = 0; i < TM; i++)
                simdgroup_load(a[i], Xs + i * 8 * LD + kk, LD);
            #pragma clang loop unroll(full)
            for (int j = 0; j < TN; j++)
                simdgroup_load(b[j], Ws + (sgid * SN + j * 8) * LD + kk, LD, ulong2(0, 0), true);
            #pragma clang loop unroll(full)
            for (int i = 0; i < TM; i++)
                #pragma clang loop unroll(full)
                for (int j = 0; j < TN; j++)
                    simdgroup_multiply_accumulate(acc[i][j], a[i], b[j], acc[i][j]);
        }
    }

    for (int pass = 0; pass < PASSES; pass++) {
        threadgroup_barrier(mem_flags::mem_threadgroup);
        const int rowBase = pass * PASS_ROWS;
        #pragma clang loop unroll(full)
        for (int i = 0; i < TM; i++) {
            const int row = i * 8 - rowBase;
            if (row < 0 || row >= PASS_ROWS) continue;
            #pragma clang loop unroll(full)
            for (int j = 0; j < TN; j++)
                simdgroup_store(acc[i][j], stage + row * OUT_LD + sgid * SN + j * 8, OUT_LD);
        }
        threadgroup_barrier(mem_flags::mem_threadgroup);
        for (uint u = tid; u < PASS_ROWS * BN / 4; u += THREADS) {
            const uint row = u / (BN / 4), c4 = u % (BN / 4);
            threadgroup const float* src = stage + row * OUT_LD + c4 * 4;
            const uint index = (m0 + rowBase + row) * p.N + n0 + c4 * 4;
            float4 v = float4(src[0], src[1], src[2], src[3]);
            *(device float4*)(Y + index) = Epi::apply(v, aux, index);
        }
    }
}

template <typename Fmt, typename Epi, int BM, int BN, int BK, int SG>
kernel void gemm_kernel(device const float* X [[buffer(0)]],
                        device const uchar* W [[buffer(1)]],
                        device float* Y [[buffer(2)]],
                        constant GemmParams& p [[buffer(3)]],
                        device const float* aux [[buffer(4)]],
                        uint2 tgid [[threadgroup_position_in_grid]],
                        uint tid [[thread_index_in_threadgroup]],
                        uint sgid [[simdgroup_index_in_threadgroup]]) {
    threadgroup float stage[gemm_stage_floats<BM, BN, BK>()];
    gemm_tile<Fmt, Epi, BM, BN, BK, SG>(X, W, Y, p, aux, stage, tgid, tid, sgid);
}

template <typename Fmt, int BM, int BN, int BK, int SG>
kernel void gemm3_kernel(device const float* X [[buffer(0)]],
                         device const uchar* W0 [[buffer(1)]],
                         device float* Y0 [[buffer(2)]],
                         constant GemmParams& p [[buffer(3)]],
                         device const uchar* W1 [[buffer(5)]],
                         device const uchar* W2 [[buffer(6)]],
                         device float* Y1 [[buffer(7)]],
                         device float* Y2 [[buffer(8)]],
                         uint3 tgid [[threadgroup_position_in_grid]],
                         uint tid [[thread_index_in_threadgroup]],
                         uint sgid [[simdgroup_index_in_threadgroup]]) {
    threadgroup float stage[gemm_stage_floats<BM, BN, BK>()];
    device const uchar* W = tgid.z == 0 ? W0 : (tgid.z == 1 ? W1 : W2);
    device float* Y = tgid.z == 0 ? Y0 : (tgid.z == 1 ? Y1 : Y2);
    gemm_tile<Fmt, EpiStore, BM, BN, BK, SG>(X, W, Y, p, X, stage, tgid.xy, tid, sgid);
}

#define GEMM_VARIANT(NAME, FMT, EPI, BM, BN, BK, SG) \
    template [[host_name(NAME)]] kernel void gemm_kernel<FMT, EPI, BM, BN, BK, SG>( \
        device const float*, device const uchar*, device float*, constant GemmParams&, device const float*, uint2, uint, uint);

#define GEMM3_VARIANT(NAME, FMT, BM, BN, BK, SG) \
    template [[host_name(NAME)]] kernel void gemm3_kernel<FMT, BM, BN, BK, SG>( \
        device const float*, device const uchar*, device float*, constant GemmParams&, \
        device const uchar*, device const uchar*, device float*, device float*, uint3, uint, uint);

#define GEMM_TILE(SUFFIX, BM, BN, BK, SG) \
    GEMM_VARIANT("gemm_q8_" SUFFIX, FmtQ8, EpiStore, BM, BN, BK, SG) \
    GEMM_VARIANT("gemm_q8_geglu_" SUFFIX, FmtQ8, EpiGeglu, BM, BN, BK, SG) \
    GEMM_VARIANT("gemm_q8_gelutimes_" SUFFIX, FmtQ8, EpiGeluTimes, BM, BN, BK, SG) \
    GEMM_VARIANT("gemm_q8_gegluquick_" SUFFIX, FmtQ8, EpiGegluQuick, BM, BN, BK, SG) \
    GEMM_VARIANT("gemm_bf16_" SUFFIX, FmtBF16, EpiStore, BM, BN, BK, SG) \
    GEMM_VARIANT("gemm_f32_" SUFFIX, FmtF32, EpiStore, BM, BN, BK, SG) \
    GEMM3_VARIANT("gemm3_q8_" SUFFIX, FmtQ8, BM, BN, BK, SG)

GEMM_TILE("32x32x32s4", 32, 32, 32, 4)
GEMM_TILE("32x64x32s4", 32, 64, 32, 4)
GEMM_TILE("64x32x32s4", 64, 32, 32, 4)
GEMM_TILE("32x64x16s4", 32, 64, 16, 4)
GEMM_TILE("64x64x16s4", 64, 64, 16, 4)
GEMM_TILE("64x64x16s8", 64, 64, 16, 8)
GEMM_TILE("64x64x32s8", 64, 64, 32, 8)
GEMM_TILE("64x128x16s8", 64, 128, 16, 8)
GEMM_TILE("64x64x16s2", 64, 64, 16, 2)
GEMM_TILE("16x32x16s4", 16, 32, 16, 4)
GEMM_TILE("16x32x16s2", 16, 32, 16, 2)
GEMM_TILE("64x128x16s4", 64, 128, 16, 4)

GEMM_TILE("8x16x32s2", 8, 16, 32, 2)

// Two independent 8x8 SIMD groups retain the short-text 8x16 dispatch shape.
// Each lane owns (fm, fn) and (fm, fn + 1) in every 8x8 fragment.
template <typename Epi>
kernel void gemm_q8_register_kernel(device const float* X [[buffer(0)]],
                                    device const uchar* W [[buffer(1)]],
                                    device float* Y [[buffer(2)]],
                                    constant GemmParams& p [[buffer(3)]],
                                    device const float* aux [[buffer(4)]],
                                    uint2 tgid [[threadgroup_position_in_grid]],
                                    uint tid [[thread_index_in_threadgroup]],
                                    uint sgid [[simdgroup_index_in_threadgroup]],
                                    uint lane [[thread_index_in_simdgroup]]) {
    const uint fm = ((lane / 4) & 4) + ((lane / 2) % 4);
    const uint fn = ((lane / 4) & 2) * 2 + (lane % 2) * 2;
    const uint m0 = tgid.y * 8;
    const uint n0 = tgid.x * 16 + sgid * 8;
    simdgroup_float8x8 acc(0.0f);

    for (uint k0 = 0; k0 < p.K; k0 += 32) {
        device const uchar* w0 = W + (n0 + fn) * p.weightRowBytes + (k0 / 32) * Q8_BLOCK_BYTES;
        device const uchar* w1 = w0 + p.weightRowBytes;
        const float scale0 = f16_to_float(ushort(w0[0]) | (ushort(w0[1]) << 8));
        const float scale1 = f16_to_float(ushort(w1[0]) | (ushort(w1[1]) << 8));
        #pragma clang loop unroll(full)
        for (uint kk = 0; kk < 32; kk += 8) {
            simdgroup_float8x8 a;
            simdgroup_float8x8 b;
            const float2 x = *(device const float2*)(X + (m0 + fm) * p.K + k0 + kk + fn);
            a.thread_elements()[0] = x.x;
            a.thread_elements()[1] = x.y;
            // B is W transposed: fragment row fm is K, column fn is an output row.
            b.thread_elements()[0] = scale0 * float(as_type<char>(w0[2 + kk + fm]));
            b.thread_elements()[1] = scale1 * float(as_type<char>(w1[2 + kk + fm]));
            simdgroup_multiply_accumulate(acc, a, b, acc);
        }
    }

    // Preserve the existing float4 epilogues and their output ordering.
    threadgroup float output[8 * 20];
    simdgroup_store(acc, output + sgid * 8, 20);
    threadgroup_barrier(mem_flags::mem_threadgroup);
    if (tid < 32) {
        const uint row = tid / 4, c4 = tid % 4;
        threadgroup const float* src = output + row * 20 + c4 * 4;
        const uint index = (m0 + row) * p.N + tgid.x * 16 + c4 * 4;
        const float4 v = float4(src[0], src[1], src[2], src[3]);
        *(device float4*)(Y + index) = Epi::apply(v, aux, index);
    }
}

#define GEMM_Q8_REGISTER_VARIANT(NAME, EPI) \
    template [[host_name(NAME)]] kernel void gemm_q8_register_kernel<EPI>( \
        device const float*, device const uchar*, device float*, constant GemmParams&, device const float*, uint2, uint, uint, uint);

GEMM_Q8_REGISTER_VARIANT("gemm_q8_register_8x16x32s2", EpiStore)
GEMM_Q8_REGISTER_VARIANT("gemm_q8_geglu_register_8x16x32s2", EpiGeglu)
GEMM_Q8_REGISTER_VARIANT("gemm_q8_gelutimes_register_8x16x32s2", EpiGeluTimes)

// Share each X fragment between the FFN projections without changing either
// accumulator's K order or staging inputs in threadgroup memory.
kernel void gemm_q8_dual_geglu_register_8x16x32s2(
    device const float* X [[buffer(0)]],
    device const uchar* Wgate [[buffer(1)]],
    device float* Y [[buffer(2)]],
    constant GemmParams& p [[buffer(3)]],
    device const uchar* Wup [[buffer(4)]],
    uint2 tgid [[threadgroup_position_in_grid]],
    uint tid [[thread_index_in_threadgroup]],
    uint sgid [[simdgroup_index_in_threadgroup]],
    uint lane [[thread_index_in_simdgroup]]) {
    const uint fm = ((lane / 4) & 4) + ((lane / 2) % 4);
    const uint fn = ((lane / 4) & 2) * 2 + (lane % 2) * 2;
    const uint m0 = tgid.y * 8;
    const uint n0 = tgid.x * 16 + sgid * 8;
    simdgroup_float8x8 gate(0.0f), up(0.0f);

    for (uint k0 = 0; k0 < p.K; k0 += 32) {
        const uint offset = (n0 + fn) * p.weightRowBytes + (k0 / 32) * Q8_BLOCK_BYTES;
        device const uchar* g0 = Wgate + offset;
        device const uchar* g1 = g0 + p.weightRowBytes;
        device const uchar* u0 = Wup + offset;
        device const uchar* u1 = u0 + p.weightRowBytes;
        const float gs0 = f16_to_float(ushort(g0[0]) | (ushort(g0[1]) << 8));
        const float gs1 = f16_to_float(ushort(g1[0]) | (ushort(g1[1]) << 8));
        const float us0 = f16_to_float(ushort(u0[0]) | (ushort(u0[1]) << 8));
        const float us1 = f16_to_float(ushort(u1[0]) | (ushort(u1[1]) << 8));
        #pragma clang loop unroll(full)
        for (uint kk = 0; kk < 32; kk += 8) {
            simdgroup_float8x8 a, g, u;
            const float2 x = *(device const float2*)(X + (m0 + fm) * p.K + k0 + kk + fn);
            a.thread_elements()[0] = x.x;
            a.thread_elements()[1] = x.y;
            g.thread_elements()[0] = gs0 * float(as_type<char>(g0[2 + kk + fm]));
            g.thread_elements()[1] = gs1 * float(as_type<char>(g1[2 + kk + fm]));
            u.thread_elements()[0] = us0 * float(as_type<char>(u0[2 + kk + fm]));
            u.thread_elements()[1] = us1 * float(as_type<char>(u1[2 + kk + fm]));
            simdgroup_multiply_accumulate(gate, a, g, gate);
            simdgroup_multiply_accumulate(up, a, u, up);
        }
    }

    constexpr uint OUT_LD = 20, OUT_SIZE = 8 * OUT_LD;
    threadgroup float output[2 * OUT_SIZE];
    simdgroup_store(gate, output + sgid * 8, OUT_LD);
    simdgroup_store(up, output + OUT_SIZE + sgid * 8, OUT_LD);
    threadgroup_barrier(mem_flags::mem_threadgroup);
    if (tid < 32) {
        const uint row = tid / 4, c4 = tid % 4;
        threadgroup const float* gs = output + row * OUT_LD + c4 * 4;
        threadgroup const float* us = gs + OUT_SIZE;
        const float4 g = float4(gs[0], gs[1], gs[2], gs[3]);
        const float4 u = float4(us[0], us[1], us[2], us[3]);
        const uint index = (m0 + row) * p.N + tgid.x * 16 + c4 * 4;
        *(device float4*)(Y + index) = float4(gelu_tanh(g.x), gelu_tanh(g.y), gelu_tanh(g.z), gelu_tanh(g.w)) * u;
    }
}

